import{_ as p,a0 as d,w as o,s as r,ao as l,I as n,x as a,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"系統管理員喜歡 systemd 的 5 個理由 | LCTT x X-CMD","titleTemplate":false,"description":"系統管理員喜歡 systemd 的 5 個理由 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系統管理員喜歡 systemd 的 5 個理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系統管理員喜歡 systemd 的 5 個理由 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20210415 5 reasons sysadmins love systemd","title":"系統管理員喜歡 systemd 的 5 個理由","tag":"202211","desc":""},"relativePath":"202211/20210415 5 reasons sysadmins love systemd.md","filePath":"[post].md"}'),h={name:"202211/20210415 5 reasons sysadmins love systemd.md"};function c(g,s,u,k,m,b){const e=d("Link");return o(),r("div",null,[s[30]||(s[30]=l(`<h1 id="系統管理員喜歡-systemd-的-5-個理由" tabindex="-1">系統管理員喜歡 systemd 的 5 個理由 <a class="header-anchor" href="#系統管理員喜歡-systemd-的-5-個理由" aria-label="Permalink to “系統管理員喜歡 systemd 的 5 個理由”">​</a></h1><blockquote><p>systemd 的速度和易用性使其成為管理現代 Linux 系統的流行方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202211/28/085754t9sztkt26452ys4s.png" alt=""></p><p>系統管理員知道，在一台運行着的<strong>現代計算機</strong>上會發生很多事情：應用程序在後台運行、預定事件等待在特定時間被觸發、事件寫入日誌文件、發送狀態報告。在以前，不同的進程可以通過一系列 Unix 工具，來進行有效地管理和監控。然而，現代的計算機運作更為複雜了：本地服務與容器化應用程序一同運行、能夠輕鬆訪問雲及其運行的集羣、實時進程、以及有比以往都多的數據。</p><p>擁有統一的管理方法不但是用户想要的，也是忙碌的系統管理員所迫切渴望的。為了完成這項重要的任務，<ruby>系統守護進程<rt> system daemon </rt></ruby> （<strong>systemd</strong>） 被開發出來，並迅速被所有主要的 Linux 發行版所採用了。</p><p>當然，systemd 並不是管理 Linux 系統的唯一方式，還有許多其他可供選擇的初始化系統，包括 sysvinit、OpenRC、runit、s6 和 BusyBox，但 systemd 將 Linux 視為一個統一的數據集，意味着 systemd 能用強大的工具對 Linux 進行一致的操作和查詢。對於忙碌的系統管理員和許多用户來説，systemd 的速度和易用性是一個重要的特性。有以下的五個原因。</p><h3 id="啓動管理" tabindex="-1">啓動管理 <a class="header-anchor" href="#啓動管理" aria-label="Permalink to “啓動管理”">​</a></h3><p>啓動 Linux 計算機可能是一件非常罕見的事情。<strong>服務器</strong>的正常運行時間通常以 <em>年</em> 來計算，而不是月或周。<strong>筆記本電腦和台式機</strong>可能會頻繁地關閉和啓動，但更多的時候它們是被掛起或休眠了。無論哪種類型，<strong>最近一次開機的時刻</strong>都可用於檢查一段時間內的計算機健康情況，因為當你在監視系統或診斷問題時，這一時刻能夠限制查看的數據量大小，從而讓你快速地找到問題所在。</p><p>如果你不記得上次啓動計算機的時間，你可以使用 systemd 的日誌記錄工具 <code>journalctl</code>，來列出計算機的所有啓動會話：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --list-boots</span></span>
<span class="line"><span>-42 7fe7c3... Fri 2020-12-04 05:13:59 - Wed 2020-12-16 16:01:23</span></span>
<span class="line"><span>-41 332e99... Wed 2020-12-16 20:07:39 - Fri 2020-12-18 22:08:13</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>-1 e0fe5f... Mon 2021-03-29 20:47:46 - Mon 2021-03-29 21:59:29</span></span>
<span class="line"><span> 0 37fbe4... Tue 2021-03-30 04:46:13 - Tue 2021-03-30 10:42:08</span></span></code></pre></div><p>最近一次啓動會話輸出在結果列表的底部，因此你可以通過管道將輸出傳輸到 <code>tail</code>，來查看最近一次啓動會話。</p><p>左側的數字（在本例中為 42、41、1 和 0）是每個啓動會話的索引號。換句話説，如果你要查看某一特定啓動會話的日誌，你可以使用這個索引號作為參數。</p><h3 id="日誌檢查" tabindex="-1">日誌檢查 <a class="header-anchor" href="#日誌檢查" aria-label="Permalink to “日誌檢查”">​</a></h3><p>查看日誌是推斷系統信息的一種重要方法。日誌提供了計算機運行的大部分事件的歷史記錄，這些記錄都是在沒有你直接監督的情況下生成的。通過日誌，你可以知道某一服務何時啓動、定時任務何時運行、哪些服務在後台運行、哪些事件運行失敗等等信息。故障排除的初始步驟是使用 systemd 的 <code>journalctl</code> 來查看日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end</span></span></code></pre></div><p><code>--pager-end</code> 選項（簡寫為 <code>-e</code>）會從 <code>journalctl</code> 的輸出末尾開始查看日誌，因此要查看更早發生的日誌，你需要向上滾動。</p><p>systemd 維護一個錯誤信息的“目錄”，錯誤信息包含錯誤記錄、可能的解決方案、支持論壇的鏈接和開發人員文檔。這個錯誤信息的“目錄”能為日誌事件提供重要的上下文，否則它可能會成為海量日誌中的一個令人困惑的信息，或者更糟的是，錯誤信息可能會完全被忽視。要將錯誤消息與日誌中的解釋性文本放在一起輸出，你可以使用 <code>--catalog</code> 選項（簡寫為 <code>-x</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end --catalog</span></span></code></pre></div><p>要進一步限定日誌輸出，你可以指定要查看哪個啓動會話的日誌。因為每個啓動會話都有索引，所以你可以使用 <code>--boot</code> 選項，來指定某個啓動會話，並僅查看該啓動會話的日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end --catalog --boot 42</span></span></code></pre></div><p>你還可以查看特定 systemd 單元的日誌。例如，要解決 SSH 服務的問題，你可以指定 <code>--unit sshd</code> 選項，來僅查看適用於 <code>sshd</code> 守護程序的日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl --pager-end \\</span></span>
<span class="line"><span>    --catalog --boot 42 \\</span></span>
<span class="line"><span>    --unit sshd</span></span></code></pre></div><h3 id="服務管理" tabindex="-1">服務管理 <a class="header-anchor" href="#服務管理" aria-label="Permalink to “服務管理”">​</a></h3><p>systemd 的第一個任務就是啓動你的計算機，systemd 會迅速、高效且有效地執行這一任務。但 systemd 一直需要管理的任務是服務管理，因為 systemd 需要確保你要運行的服務確實在你的會話期間啓動，並繼續運行。systemd 的這一功能非常穩健，因為理論上即使是一個崩潰的服務也可以在沒有你干預的情況下重新啓動。</p><p>你可以通過使用 <code>systemctl</code> 命令來讓 systemd 管理服務，並能查看定義服務的 <ruby>單元文件<rt> unit file </rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl cat sshd</span></span>
<span class="line"><span># /usr/lib/systemd/system/sshd.service</span></span>
<span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=OpenSSH server daemon</span></span>
<span class="line"><span>Documentation=man:sshd(8) man:sshd_config(5)</span></span>
<span class="line"><span>After=network.target sshd-keygen.target</span></span>
<span class="line"><span>Wants=sshd-keygen.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=notify</span></span>
<span class="line"><span>EnvironmentFile=-/etc/crypto-policies/back-ends/opensshserver.config</span></span>
<span class="line"><span>EnvironmentFile=-/etc/sysconfig/sshd</span></span>
<span class="line"><span>ExecStart=/usr/sbin/sshd -D $OPTIONS $CRYPTO_POLICY</span></span>
<span class="line"><span>ExecReload=/bin/kill -HUP $MAINPID</span></span>
<span class="line"><span>KillMode=process</span></span>
<span class="line"><span>Restart=on-failure</span></span>
<span class="line"><span>RestartSec=42s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre></div><p>大多數單元文件都在 <code>/usr/lib/systemd/system/</code> 目錄下，但是你也可以用局部更改來修改配置，請使用以下的方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl edit sshd</span></span></code></pre></div><p>你可以通過 <code>is-active</code> 選項，來查看某一服務當前是否處於活動狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl is-active sshd</span></span>
<span class="line"><span>active</span></span>
<span class="line"><span>$ systemctl is-active foo</span></span>
<span class="line"><span>inactive</span></span></code></pre></div><p>同樣地，你可以通過 <code>is-failed</code> 選項，來查看某一服務是否運行失敗了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl is-failed sshd</span></span></code></pre></div><p>使用以下命令，來啓動或者停止某一服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl stop sshd</span></span>
<span class="line"><span>$ systemctl start sshd</span></span></code></pre></div><p>使用以下命令，讓某一服務在開機時自啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl enable sshd</span></span></code></pre></div><p>添加 <code>--now</code> 選項，讓某一服務在開機時啓動並在當前會話中立即啓動。</p><h3 id="定時器管理" tabindex="-1">定時器管理 <a class="header-anchor" href="#定時器管理" aria-label="Permalink to “定時器管理”">​</a></h3>`,38)),n("p",null,[s[1]||(s[1]=a("在以前，當你想在 Linux 上自動執行一項任務時，你可以使用的工具是 ",-1)),s[2]||(s[2]=n("code",null,"cron",-1)),s[3]||(s[3]=a("。如今，",-1)),s[4]||(s[4]=n("code",null,"cron",-1)),s[5]||(s[5]=a(" 命令仍能使用，但對於在 Linux 上自動執行一項任務，也有一些其他好用的替代方案。例如，",-1)),t(e,{href:"https://opensource.com/article/21/2/linux-automation"},{default:i(()=>[...s[0]||(s[0]=[a("anacron 命令",-1)])]),_:1}),s[6]||(s[6]=a(" 是一個多功能的、類似於 ",-1)),s[7]||(s[7]=n("code",null,"cron",-1)),s[8]||(s[8]=a(" 的系統，它能夠運行在停機期間可能會錯過的任務。",-1))]),n("p",null,[s[10]||(s[10]=a("計劃的事件就是在特定時間需要激活的服務。systemd 管理一個名為 ",-1)),t(e,{href:"https://opensource.com/article/20/7/systemd-timers"},{default:i(()=>[...s[9]||(s[9]=[a("定時器",-1)])]),_:1}),s[11]||(s[11]=a(" 的工具，它類似 cron 的功能。你可以使用以下命令，來列出活動中的定時器：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-timers</span></span>
<span class="line"><span>NEXT                          LEFT      </span></span>
<span class="line"><span>Tue 2021-03-30 12:37:54 NZDT  16min left [...]</span></span>
<span class="line"><span>Wed 2021-03-31 00:00:00 NZDT  11h left [...]</span></span>
<span class="line"><span>Wed 2021-03-31 06:42:02 NZDT  18h left [...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3 timers listed.</span></span>
<span class="line"><span>Pass --all to see loaded but inactive timers, too.</span></span></code></pre></div><p>你可以使用以下命令，來像啓用服務一樣啓用定時器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl enable myMonitor.timer</span></span></code></pre></div><h3 id="目標管理" tabindex="-1">目標管理 <a class="header-anchor" href="#目標管理" aria-label="Permalink to “目標管理”">​</a></h3><p><ruby>目標<rt>target</rt></ruby> 是 systemd 的最後一個主要組成部分。像服務和定時器一樣，目標也是一個單元文件，也可以以相同的方式啓動和啓用。目標的獨特之處在於它們可以將其他單元文件任意分組。例如，你可能希望開機啓動到文本控制台界面而不是圖形桌面，因此有一個 <code>multi-user</code> 目標。但是，<code>multi-user</code> 目標只是沒有包括桌面單元文件的 <code>graphical</code> 目標。</p><p>簡而言之，目標是一種將服務、定時器甚至其他的目標集合在一起，以表示機器的預期狀態的簡單方法。</p><p>事實上，在 systemd 中，重啓、關機或關閉操作只是一個目標而已。</p><p>你可以使用 <code>list-unit-files</code> 選項，用 <code>--type</code> 選項將其限制為 <code>target</code> 來列出所有可用的目標：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-unit-files --type target</span></span></code></pre></div><h3 id="使用-systemd-對計算機進行控制管理" tabindex="-1">使用 systemd 對計算機進行控制管理 <a class="header-anchor" href="#使用-systemd-對計算機進行控制管理" aria-label="Permalink to “使用 systemd 對計算機進行控制管理”">​</a></h3><p>現代的 Linux 使用 systemd 進行服務管理和日誌檢查。從個人的 Linux 系統到企業服務器，systemd 都能提供有效的監控，並且十分易於維護。你越頻繁地使用 systemd，systemd 對你而言就會變得越容易預測和直觀，你就會明白系統的不同部分是如何相互關聯的。</p>`,11)),n("p",null,[s[13]||(s[13]=a("為了更好地熟悉 systemd，請現在就開始使用它吧。請 ",-1)),t(e,{href:"https://opensource.com/downloads/linux-systemd-cheat-sheet"},{default:i(()=>[...s[12]||(s[12]=[a("下載關於 systemd 相關命令的備忘錄",-1)])]),_:1}),s[14]||(s[14]=a("，你可以在實際使用 systemd 中經常參考這個備忘錄，這樣你就能更快熟悉使用 systemd 啦！",-1))]),s[32]||(s[32]=n("hr",null,null,-1)),n("p",null,[s[16]||(s[16]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/21/4/sysadmins-love-systemd"},{default:i(()=>[...s[15]||(s[15]=[a("https://opensource.com/article/21/4/sysadmins-love-systemd",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[17]||(s[17]=[a("Seth Kenlon",-1)])]),_:1}),s[22]||(s[22]=a(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[18]||(s[18]=[a("lujun9972",-1)])]),_:1}),s[23]||(s[23]=a(" 譯者：",-1)),t(e,{href:"https://github.com/chai001125"},{default:i(()=>[...s[19]||(s[19]=[a("chai001125",-1)])]),_:1}),s[24]||(s[24]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[25]||(s[25]=[a("LCTT",-1)])]),_:1}),s[28]||(s[28]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[26]||(s[26]=[a("Linux中國",-1)])]),_:1}),s[29]||(s[29]=a(" 榮譽推出",-1))])])}const v=p(h,[["render",c]]);export{x as __pageData,v as default};
